# (e.g. "/save") with 400 InvalidQueryStringKey before the function is invoked.
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }

tests/forms_test.sh.text:
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# Every rendered form URL must have only query keys the Cirrus function URL accepts (A-Za-z0-9_.-)
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="//;s/"$//' | while read -r u; do
    k=${u#\?}; k=${k%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "bad query key: $k"; exit 1; }
  done || fail=1
done
# Each form's operation round-trips through render -> handle
for f in event seat refund; do
  for a in $(cat app/forms/$f.form); do
    u=$(bash bin/render $f | grep -o "action=\"[^\"]*=$a\"" | sed 's/action="//;s/"$//')
    bash bin/handle POST "/x$u" | grep -q "^200 $a" || { echo "roundtrip $f/$a"; fail=1; }
  done
done
exit $fail

